function subarraySum(nums, k) {
  const seen = new Map([[0, 1]]);                    // prefix sum -> times seen so far
  let sum = 0, count = 0;
  for (const x of nums) {
    sum += x;
    count += seen.get(sum - k) ?? 0;                  // an earlier prefix of sum - k leaves exactly k
    seen.set(sum, (seen.get(sum) ?? 0) + 1);
  }
  return count;
}

int subarraySum(int[] nums, int k) {
    Map<Integer, Integer> seen = new HashMap<>();       // prefix sum -> times seen so far
    seen.put(0, 1);
    int sum = 0, count = 0;
    for (int x : nums) {
        sum += x;
        count += seen.getOrDefault(sum - k, 0);          // an earlier prefix of sum - k leaves exactly k
        seen.merge(sum, 1, Integer::sum);
    }
    return count;
}

int subarraySum(vector<int>& nums, int k) {
    unordered_map<int, int> seen{{0, 1}};              // prefix sum -> times seen so far
    int sum = 0, count = 0;
    for (int x : nums) {
        sum += x;
        auto it = seen.find(sum - k);
        if (it != seen.end()) count += it->second;      // an earlier prefix of sum - k leaves exactly k
        seen[sum]++;
    }
    return count;
}
